// One bad value makes BigQuery reject the whole load job, so timestamps are checked here:
// an unparseable upisano is replaced with now, an unparseable objavljeno becomes null.
const nowIso = new Date().toISOString();
const okTs = v => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}T/.test(v) && !isNaN(Date.parse(v));
const items = $input.all();
const ndjson = items.map(i => {
  const j = { ...i.json };
  if (!okTs(j.upisano)) j.upisano = nowIso;
  if (j.objavljeno !== null && j.objavljeno !== undefined && !okTs(j.objavljeno)) j.objavljeno = null;
  return JSON.stringify(j);
}).join('\n');

const metadata = {
  configuration: {
    load: {
      destinationTable: {
        projectId: 'stan-hunter',
        datasetId: 'stan_hunter',
        tableId: 'listings'
      },
      sourceFormat: 'NEWLINE_DELIMITED_JSON',
      writeDisposition: 'WRITE_APPEND'
    }
  }
};

return [{ json: { metadata, ndjson, count: items.length } }];

