// Source health. Run* nodes use continueRegularOutput, so a failing source does not fail the orchestrator
// and does not trigger Error alerts. Errors or 0 listings per source are caught here instead.
// Alert after 2 bad runs in a row (~1 h), reminder every 12 (~6 h), message when the source recovers.
const SOURCES = { Run4zida: '4zida', RunCityExpert: 'CityExpert', RunNekretnine: 'Nekretnine.rs' };
const ALERT_AFTER = 2;
const REMIND_EVERY = 12;
// The Telegram node sends HTML, so <, > and & must be escaped.
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const store = $getWorkflowStaticData('global');
const health = { ...(store.sourceHealth || {}) };
const lines = [];

for (const [nodeName, label] of Object.entries(SOURCES)) {
  let items;
  try { items = $(nodeName).all(); } catch (e) { continue; } // node did not run in this execution
  const errItem = items.find(i => i.json.error);
  const count = items.filter(i => i.json.id).length;
  let problem = null;
  if (errItem) {
    const e = errItem.json.error;
    problem = 'greška: ' + esc(String(typeof e === 'string' ? e : (e?.message ?? JSON.stringify(e))).slice(0, 150));
  } else if (count === 0) {
    problem = '0 oglasa';
  }
  const prev = health[label] || { fails: 0, alerted: false };
  if (problem) {
    const fails = prev.fails + 1;
    const alert = fails === ALERT_AFTER || (fails > ALERT_AFTER && (fails - ALERT_AFTER) % REMIND_EVERY === 0);
    if (alert) lines.push(`❌ ${label}: ${problem} (${fails}× zaredom)`);
    health[label] = { fails, alerted: prev.alerted || alert };
  } else {
    if (prev.alerted) lines.push(`✅ ${label} ponovo radi (${count} oglasa)`);
    health[label] = { fails: 0, alerted: false };
  }
}

store.sourceHealth = health;
if (!lines.length) return [];
return [{ json: { text: `🩺 Stan Hunter izvori\n${lines.join('\n')}` } }];

// Same flat on several sites: fingerprint = price + m² + rooms + municipality (diacritics and the word "opština" removed).
// Municipality, not neighbourhood: sites name the neighbourhood of the same flat differently (18.11.: 4zida "Pravni fakultet - Vračar" vs Nekretnine.rs "Hram Svetog Save - Neimar - Čubura").
// The fingerprint only proposes candidates; Claude vision decides (`Dedup - same flat check`), because two different flats can share it.
// Each fingerprint keeps the last 3 flats sent with it (newest first) and a listing is compared with all of them, including listings
// from this same run (20.11.: after a day offline, two new 4zida ads of one flat were each compared only with an older, different flat).
// route: 'new' = full message | 'check' = compare with dup_candidates | 'legacy' = collides only with entries without a photo (before 19.11.) → one-line note.
// Without price, size or location there is no fingerprint → full message. Fingerprints live 30 days in static data (production runs only).
const norm = s => String(s ?? '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/g, 'd').replace(/\bopstina\b/g, '').replace(/\s+/g, ' ').trim();
const DAY = 24 * 60 * 60 * 1000;
const KEEP = 3;
const now = Date.now();
const store = $getWorkflowStaticData('global');
const seen = {};
for (const [k, v] of Object.entries(store.sentFingerprints || {})) {
  // Formats: list of entries (from 20.11.), one entry (19.11.), only a timestamp (before 19.11.).
  const list = (Array.isArray(v) ? v : [v]).map(e => (typeof e === 'number' ? { t: e } : e)).filter(e => e && e.t && now - e.t < 30 * DAY);
  if (list.length) seen[k] = list.slice(0, KEEP);
}
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const place = norm(j.opstina) || norm(j.naselje);
  if (j.cena === null || j.cena === undefined || j.m2 === null || j.m2 === undefined || !place) {
    out.push({ json: { ...j, route: 'new' } });
    continue;
  }
  const base = `${j.cena}|${j.m2}|${j.sobe ?? '-'}`;
  const fp = `${base}|o:${place}`;
  const prev = [];
  for (const e of [...(seen[fp] || []), ...(seen[`${base}|${norm(j.naselje)}`] || [])]) { // second key: format before 18.11.
    if (e.id && prev.some(p => p.id === e.id)) continue;
    prev.push(e);
  }
  const candidates = prev.filter(e => e.slika);
  if (candidates.length) out.push({ json: { ...j, route: 'check', dup_candidates: candidates } });
  else if (prev.length) out.push({ json: { ...j, route: 'legacy' } });
  else out.push({ json: { ...j, route: 'new' } });
  const entry = { t: now, id: j.id, url: j.url, izvor: j.izvor, slika: j.slika, cena: j.cena, m2: j.m2, sobe: j.sobe ?? null, opstina: j.opstina, naselje: j.naselje };
  seen[fp] = [entry, ...(seen[fp] || []).filter(e => e.id !== j.id)].slice(0, KEEP);
}
store.sentFingerprints = seen;
return out;

// New = listings whose id is not in BigQuery yet.
// Previously: Remove Duplicates (n8n memory) → a listing deleted from the table (❌ button, nightly Cleanup) never came back.
// Now: if the site lists it again, it returns to the table. If the BigQuery query fails, the run fails (alert) and listings are picked up next run.
const r = $input.first().json;
const rows = r.rows || [];
if (r.jobComplete === false || Number(r.totalRows ?? rows.length) > rows.length) {
  throw new Error(`GetKnownIds: nepotpun odgovor BigQuery-ja (${rows.length} od ${r.totalRows})`);
}
const known = new Set(rows.map(row => row.f[0].v));
const seen = new Set();
return $('KeepValidListings').all().filter(i => {
  const id = i.json.id;
  if (known.has(id) || seen.has(id)) return false;
  seen.add(id);
  return true;
});

// Layer B: `Enrich - listing description (Claude)` returns { id, fields } for 4zida listings whose description was read.
// Photos: `Enrich - photo quality (Claude vision)` returns { id, kvalitet, kvalitet_opis } for listings with a cover photo.
// Both are merged into the original new listings. If enrichment fails or returns nothing, listings continue unchanged.
// Structured fields from the site (layer A) win; the LLM only fills what is unknown.
const orig = $('OnlyNewFlats').all();
const extra = {};
for (const i of $('EnrichNew').all()) if (i.json && i.json.id && i.json.enrich_ok === true) extra[i.json.id] = i.json;
const photos = {};
for (const i of $input.all()) if (i.json && i.json.id && i.json.photo_ok === true) photos[i.json.id] = i.json;
return orig.map(i => {
  const j = { ...i.json };
  const ph = photos[j.id];
  if (ph) { j.kvalitet = ph.kvalitet ?? null; j.kvalitet_opis = ph.kvalitet_opis ?? null; }
  const e = extra[j.id];
  if (!e) return { json: j };
  const unknown = v => v === null || v === undefined || v === '' || v === 'nepoznato';
  j.provizija = e.provizija ?? j.provizija ?? null;
  j.rezije_eur = e.rezije_eur ?? j.rezije_eur ?? null;
  j.min_period_meseci = e.min_period_meseci ?? j.min_period_meseci ?? null;
  j.sumnjiv_oglas = e.sumnjiv_oglas === true;
  j.sumnjiv_razlog = e.sumnjiv_razlog ?? null;
  if (unknown(j.depozit_eur) && e.depozit_eur !== null && e.depozit_eur !== undefined) j.depozit_eur = e.depozit_eur;
  if (unknown(j.namesten) && !unknown(e.namesten)) j.namesten = e.namesten;
  if (unknown(j.kucni_ljubimci) && !unknown(e.kucni_ljubimci)) j.kucni_ljubimci = e.kucni_ljubimci;
  if (j.namesten === 'ne') j.prosao_filter = false; // filter: unfurnished does not pass
  return { json: j };
});

// Poll result of the BigQuery load job (WaitForLoad repeats GET until state = DONE, max ~20 s).
// errorResult → fail the run (Error alerts); nothing was inserted, so the same listings are picked up next run.
// Still RUNNING or the poll itself failed → continue; messages then go out without a score.
const last = $input.all().at(-1)?.json ?? {};
const state = last.status?.state ?? 'UNKNOWN';
const err = last.status?.errorResult;
if (err) throw new Error(`BigQuery load job: ${String(err.message ?? err.reason ?? 'error').slice(0, 300)}`);
const ids = $('ApplyEnrichment').all().map(i => i.json.id).filter(Boolean);
return [{ json: { load_state: state, ids } }];

// The 0–100 score comes from the BigQuery view listings_scored (the same formula /top uses), so it is computed once.
// Missing score (query failed, load still running) → the message is sent without it.
const r = $input.first().json;
const fields = (r.schema?.fields || []).map(f => f.name);
const scores = {};
for (const row of r.rows || []) {
  const o = Object.fromEntries(row.f.map((c, i) => [fields[i], c.v]));
  scores[o.id] = { ocena: o.ocena === null ? null : Math.round(Number(o.ocena)), lok: o.lok === null ? null : Number(o.lok) };
}
return $('ApplyEnrichment').all().map(i => ({ json: { ...i.json, ocena: scores[i.json.id]?.ocena ?? null, lok: scores[i.json.id]?.lok ?? null } }));

// Input for `Dedup - same flat check (Claude vision)`: one pair per candidate (the new listing + a flat already sent with the
// same fingerprint, newest first, max 3). ApplyDupResult merges the verdicts back into one item per listing.
const out = [];
$input.all().forEach((item, i) => {
  const { dup_candidates, route, ...novi } = item.json;
  (dup_candidates || []).forEach((c, rank) => out.push({ json: { novi, postojeci: { ...c, rank } }, pairedItem: { item: i } }));
});
return out;

// Verdicts back on the listings, one item per listing. Same flat = isti === true for at least one candidate; the note points to the
// oldest match (the flat most likely sent as a full message). false or null for all (could not compare, API error) → full message.
const fmt = t => (t ? DateTime.fromMillis(t).setZone('Europe/Belgrade').toFormat('dd.MM. HH:mm') : '');
const groups = new Map();
for (const { json: p } of $('BuildDupPair').all()) {
  if (p.novi && !groups.has(p.novi.id)) groups.set(p.novi.id, { L: p.novi, first: p.postojeci, hit: null, razlog: null });
}
for (const { json: r } of $input.all()) {
  const g = r.novi && groups.get(r.novi.id);
  if (!g || !r.postojeci) continue;
  if (r.isti === true) {
    if (!g.hit || (r.postojeci.rank ?? 0) > (g.hit.c.rank ?? 0)) g.hit = { c: r.postojeci, razlog: r.razlog ?? null };
  } else if (!g.razlog && r.razlog) g.razlog = r.razlog;
}
return [...groups.values()].map(({ L, first, hit, razlog }) => {
  const c = hit ? hit.c : first;
  return { json: { ...L, dup_isti: !!hit, dup_razlog: hit ? hit.razlog : razlog, dup_izvor: c.izvor, dup_url: c.url, dup_kada: fmt(c.t) } };
});

